import React from 'react';
import { render } from '@testing-library/react';
import { Chip } from '../../../..';

describe('ChipDeleteIcon', () => {
  it('should be shown a console warn when the Chip.DeleteIcon is called outside a Chip.Root', () => {
    jest.spyOn(console, 'warn').mockImplementation();
    render(<Chip.DeleteIcon onDelete={() => null} />);
    expect(console.warn).toHaveBeenCalledWith(
      expect.stringContaining(
        'Missing chip context, make sure that Chip.DeleteIcon is being used as a child of Chip.Root'
      )
    );
  });
});
